        let m8 = v[2] * v[4];
        let m9 = v[3] * v[4];
        let m10 = v[0] * v[1];
        let m11 = v[0] * v[2];
        let m12 = v[0] * v[3];
        let m13 = v[0] * v[4];
        let m14 = m0 + m1;
        let m15 = m2 - m3;
        let m16 = m0 - m1;
        let m17 = m2 + m3;
        let m18 = m16 - m15;
        let m19 = m4 * T::from_i64(2);
        let m20 = m5 * T::from_i64(2);
        let m21 = m6 * T::from_i64(2);
        let m22 = m10 * T::from_i64(2);
        let m23 = m15 + m16;
        let m24 = -m23;
        let m25 = m7 * T::from_i64(2);
        let m26 = m8 * T::from_i64(2);
        let m27 = m11 * T::from_i64(2);
        let m28 = m17 - m14;
        let m29 = m9 * T::from_i64(2);
        let m30 = m12 * T::from_i64(2);
        let m31 = -m21;
        let m32 = -m26;
        let m33 = -m29;
        let m34 = m14 + m17;
        let m35 = -m34;
        let m36 = m13 * T::from_i64(2);
